 1	import java.util.ArrayDeque;
 2	import java.util.Deque;
 3	import java.util.Objects;
 4	
 5	public class BalancedParentheses {
 6	    private static final String DEFAULT_SAMPLE = "[()()]{}";
 7	
 8	    private BalancedParentheses() {}
 9	
10	    public static boolean isBalanced(String s) {
11	        Objects.requireNonNull(s, "input");
12	        Deque<Character> expectedClosings = new ArrayDeque<>();
13	
14	        for (int i = 0; i < s.length(); i++) {
15	            BracketToken token = BracketToken.from(s.charAt(i));
16	            if (token == null) {
17	                continue;
18	            }
19	
20	            if (token.isOpening()) {
21	                expectedClosings.push(token.matchingCharacter());
22	                continue;
23	            }
24	
25	            if (expectedClosings.isEmpty() || expectedClosings.pop() != token.character()) {
26	                return false;
27	            }
28	        }
29	
30	        return expectedClosings.isEmpty();
31	    }
32	
33	    public static void main(String[] args) {
34	        String s = args.length > 0 ? args[0] : DEFAULT_SAMPLE;
35	        System.out.println((isBalanced(s) ? "true" : "false"));
36	    }
37	
38	    private record BracketToken(char character, char matchingCharacter, boolean opening) {
39	        private static BracketToken from(char candidate) {
40	            return switch (candidate) {
41	                case '(' -> new BracketToken(candidate, ')', true);
42	                case '{' -> new BracketToken(candidate, '}', true);
43	                case '[' -> new BracketToken(candidate, ']', true);
44	                case ')' -> new BracketToken(candidate, '(', false);
45	                case '}' -> new BracketToken(candidate, '{', false);
46	                case ']' -> new BracketToken(candidate, '[', false);
47	                default -> null;
48	            };
49	        }
50	
51	        private boolean isOpening() {
52	            return opening;
53	        }
54	    }
55	}

